"""Draws the logo of Kasauti Capital Partners, the fictional investment firm, in code. Nothing is generated by a model.

It is a ring round a tilted touchstone with three rising gold bars on it, in the two colours of the firm's kit.

uv run python tools/draw_kasauti_logo.py
"""

from pathlib import Path

import yaml
from PIL import Image, ImageDraw

ROOT = Path(__file__).resolve().parent.parent
FOLDER = ROOT / "brands" / "demo-investment-firm"
SIZE, DRAWN_AT = 1024, 2048
CENTRE = DRAWN_AT // 2
RING_OUTER, RING_INNER = 960, 906
STONE_WIDTH, STONE_HEIGHT, STONE_CORNER = 1300, 780, 120
TILT_DEGREES = 10
# Three bars that stand on one line, this far above the stone's lower edge, each taller than the one before.
BAR_WIDTH, BAR_GAP, BAR_HEIGHTS, BAR_CORNER, BAR_MARGIN = 170, 100, (240, 400, 560), 44, 120


def colours() -> tuple[tuple[int, int, int], tuple[int, int, int]]:
    kit = yaml.safe_load((FOLDER / "kit.md").read_text(encoding="utf-8").split("---")[1])["colors"]
    return tuple(tuple(int(kit[name][at:at + 2], 16) for at in (1, 3, 5)) for name in ("primary", "accent"))


def draw() -> Image.Image:
    primary, accent = colours()
    ring = Image.new("RGBA", (DRAWN_AT, DRAWN_AT), (0, 0, 0, 0))
    pen = ImageDraw.Draw(ring)
    pen.ellipse((CENTRE - RING_OUTER, CENTRE - RING_OUTER, CENTRE + RING_OUTER, CENTRE + RING_OUTER), fill=(*primary, 255))
    pen.ellipse((CENTRE - RING_INNER, CENTRE - RING_INNER, CENTRE + RING_INNER, CENTRE + RING_INNER), fill=(*primary, 0))
    # The stone is drawn upright and then tilted. Its empty surround is the primary colour with no opacity, so tilting leaves no dark fringe.
    stone = Image.new("RGBA", (DRAWN_AT, DRAWN_AT), (*primary, 0))
    pen = ImageDraw.Draw(stone)
    left, top = CENTRE - STONE_WIDTH // 2, CENTRE - STONE_HEIGHT // 2
    pen.rounded_rectangle((left, top, left + STONE_WIDTH, top + STONE_HEIGHT), STONE_CORNER, fill=(*primary, 255))
    bars_width = len(BAR_HEIGHTS) * BAR_WIDTH + (len(BAR_HEIGHTS) - 1) * BAR_GAP
    foot = top + STONE_HEIGHT - BAR_MARGIN
    for place, height in enumerate(BAR_HEIGHTS):
        x = CENTRE - bars_width // 2 + place * (BAR_WIDTH + BAR_GAP)
        pen.rounded_rectangle((x, foot - height, x + BAR_WIDTH, foot), BAR_CORNER, fill=(*accent, 255))
    tilted = stone.rotate(TILT_DEGREES, resample=Image.BICUBIC, center=(CENTRE, CENTRE))
    return Image.alpha_composite(ring, tilted).resize((SIZE, SIZE), Image.LANCZOS)


def main() -> None:
    out = FOLDER / "logo.png"
    draw().save(out, optimize=True)
    print(f"Wrote {out.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
